const cp = global.get('child_process');
const fs = global.get('fs');
const path = global.get('path');
const root = global.get('projectRoot') || '.';
const jobsPath = path.join(root, 'data', 'jobs.json');

let jobs = [];
try {
  if (fs.existsSync(jobsPath)) {
    jobs = JSON.parse(fs.readFileSync(jobsPath, 'utf8'));
  }
} catch (e) { jobs = []; }

const jobId = msg.req.params.id;
const job = jobs.find(j => j.id === jobId);
if (!job) {
  msg.statusCode = 404;
  msg.headers = { 'content-type': 'application/json' };
  msg.payload = { error: 'Job inexistent.' };
  node.send(msg);
  return;
}

const textToSynthesize = String(msg.payload?.text || job.prompt || job.title || '').trim();
const lang = String(msg.payload?.lang || 'ro').trim();

// Run Python media_tools.py via uv run
const scriptPath = path.join(root, 'scripts', 'media_tools.py');
const args = ['run', 'python', scriptPath, 'tts', '--text', textToSynthesize, '--lang', lang];

cp.execFile('uv', args, { cwd: root, timeout: 25000 }, (error, stdout, stderr) => {
  msg.headers = { 'content-type': 'application/json' };
  if (error) {
    msg.statusCode = 500;
    msg.payload = { error: 'Generare TTS eșuată: ' + (stderr || error.message) };
    node.send(msg);
    return;
  }
  try {
    const res = JSON.parse(stdout.trim());
    job.audioUrl = `/api/media/${res.filename}`;
    job.audioFile = res.filename;
    job.audioDuration = res.duration;
    job.status = 'ready';
    job.updatedAt = new Date().toISOString();
    fs.writeFileSync(jobsPath, JSON.stringify(jobs, null, 2), 'utf8');
    flow.set('jobs', jobs);
    msg.statusCode = 200;
    msg.payload = { ok: true, job, media: res };
  } catch (parseErr) {
    msg.statusCode = 500;
    msg.payload = { error: 'Răspuns invalid de la generatorul TTS', raw: stdout };
  }
  node.send(msg);
});

